<script setup lang="ts">
import type {SixModelResult} from '../api/review'
import {modelNames} from '../api/training'
import {summarizeEvidence} from '../review-summary'
defineProps<{items:SixModelResult[];selected:string}>()
defineEmits<{select:[family:string]}>()
const warnings=(item:SixModelResult)=>new Set(item.result.evidence.filter(e=>summarizeEvidence(e,0).warning).map(e=>e.sourceWorkId)).size
</script>
<template><section v-if="items.length" class="six-model-results"><div class="six-heading"><h3>六模型审核</h3><span>主模型 {{modelNames[items.find(i=>i.primary)?.family||'']}} · 点击切换证据</span></div><div class="six-grid"><button v-for="item in items" :key="item.modelId" type="button" :class="{selected:item.family===selected,warning:warnings(item)>0}" :aria-pressed="item.family===selected" @click="$emit('select',item.family)"><span class="family">{{item.family.toUpperCase()}}<small v-if="item.primary">主模型</small></span><strong>{{warnings(item)>0?'疑似复用':'未提示复用'}}</strong><span class="six-meta">{{warnings(item)}} 个来源 · {{item.scoredPairs}} 组比对</span><span class="six-meta">验证 Macro-F1 {{(item.calibration.macroF1*100).toFixed(1)}}%</span></button></div></section></template>
<style scoped>.six-model-results{margin-bottom:14px;border:1px solid var(--line);padding:12px}.six-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;gap:10px}.six-heading h3{margin:0;font-size:14px}.six-heading>span{font-size:12px;color:var(--muted)}.six-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.six-grid button{display:flex;flex-direction:column;gap:6px;padding:10px;text-align:left;border:1px solid var(--line);border-radius:0;background:var(--canvas);color:var(--heading);cursor:pointer}.six-grid button.selected{border-color:var(--el-color-primary);box-shadow:inset 0 2px var(--el-color-primary);background:var(--soft)}.six-grid button:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}.family{font-size:15px;font-weight:650;display:flex;justify-content:space-between;gap:4px}.family small{font-size:10px;color:var(--el-color-primary)}.six-grid strong{font-size:13px}.six-grid .warning strong{color:var(--el-color-warning)}.six-meta{font-size:11px;color:var(--muted)}@media(max-width:1100px){.six-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.six-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.six-heading{align-items:flex-start;flex-direction:column}}</style>
